    def checkPartitioning(self, s: str) -> bool:
        n = len(s)

        @lru_cache(None)
        def pal(i,j):
            if i == j:
                return True
            if s[i] != s[j]:
                return False
            if i+1 == j:
                return True
            else:
                return pal(i+1,j-1)

        for i in range(n-2):
